app.post("/api/users", auth, requireRole("admin", "supervisor"), async (req, res) => {
  const b = req.body || {};
  if (!b.name || !b.phone) return res.status(400).json({ error: "name_and_phone_required" });
  const existing = b.id ? await db.get("SELECT * FROM users WHERE id = ?", [b.id]) : null;
  const dupe = await db.get("SELECT * FROM users WHERE phone = ? AND id <> ?", [b.phone, b.id || "-"]);
  if (dupe) return res.status(400).json({ error: "phone_already_used" });
  const id = b.id || uid();
  const role = ["didi", "supervisor", "admin", "viewer"].includes(b.role) ? b.role : "didi";
  if (req.user.role === "supervisor" && role !== "didi") return res.status(403).json({ error: "supervisor_can_only_manage_didi" });
  await db.upsert("users", {
    id,
    name: b.name,
    phone: String(b.phone).trim(),
    pin: b.pin ? hashPin(b.pin) : existing ? existing.pin : hashPin("1234"),
    role,
    block_id: b.block_id || null,
    ward_id: b.ward_id || null,
    shg_name: b.shg_name || null,
    active: b.active === 0 ? 0 : 1,
    created_at: existing ? existing.created_at : nowISO()
  }, "id");
  const out = await db.get("SELECT id,name,phone,role,block_id,ward_id,shg_name,active FROM users WHERE id = ?", [id]);
  res.json(out);
});
