app.get("/api/dashboard", auth, async (req, res) => {
  const from = req.query.from || new Date(Date.now() - 29 * 864e5).toISOString().slice(0, 10);
  const to = req.query.to || today();
  const sc = await scopeFor(req.user);
  let extra = "", extraParams = [];
  if (req.query.block_id) {
    const w = await db.all("SELECT id FROM wards WHERE block_id = ?", [req.query.block_id]);
    const ids = w.map((x) => x.id);
    extra = ids.length ? ` AND ward_id IN (${ids.map(() => "?").join(",")})` : " AND 1=0";
    extraParams = ids;
  }
  if (req.query.ward_id) {
    extra += " AND ward_id = ?";
    extraParams.push(req.query.ward_id);
  }
  const W = `${sc.sql}${extra}`;
  const P = [...sc.params, ...extraParams];
  const hh = await db.get(`SELECT COUNT(*) AS n FROM households WHERE active=1 AND ${W}`, P);
  const totalHH = Number(hh.n) || 0;
  const colAgg = await db.get(
    `SELECT COUNT(*) AS services, COUNT(DISTINCT household_id) AS covered,
            COALESCE(SUM(wet_kg),0) AS wet, COALESCE(SUM(dry_kg),0) AS dry, COALESCE(SUM(hazard_kg),0) AS hazard,
            COALESCE(SUM(segregated),0) AS seg
     FROM collections WHERE service_date BETWEEN ? AND ? AND ${W}`,
    [from, to, ...P]
  );
  const todayAgg = await db.get(
    `SELECT COUNT(*) AS services, COUNT(DISTINCT household_id) AS covered
     FROM collections WHERE service_date = ? AND ${W}`,
    [today(), ...P]
  );
  const payAgg = await db.get(
    `SELECT COALESCE(SUM(amount),0) AS total, COUNT(*) AS n FROM payments
     WHERE ts BETWEEN ? AND ? AND ${W}`,
    [from, to + "T23:59:59Z", ...P]
  );
  const griev = await db.all(`SELECT status, COUNT(*) AS n FROM grievances WHERE ${W} GROUP BY status`, P);
  const daily = await db.all(
    `SELECT service_date AS d, COUNT(*) AS services, COUNT(DISTINCT household_id) AS covered,
            COALESCE(SUM(wet_kg+dry_kg+hazard_kg),0) AS kg
     FROM collections WHERE service_date BETWEEN ? AND ? AND ${W}
     GROUP BY service_date ORDER BY service_date`,
    [from, to, ...P]
  );
  const byWard = await db.all(
    `SELECT w.id, w.name_hi, w.name_en, w.block_id, w.kind,
            (SELECT COUNT(*) FROM households h WHERE h.ward_id=w.id AND h.active=1) AS households,
            (SELECT COUNT(DISTINCT c.household_id) FROM collections c WHERE c.ward_id=w.id AND c.service_date=?) AS covered_today,
            (SELECT COUNT(*) FROM collections c WHERE c.ward_id=w.id AND c.service_date BETWEEN ? AND ?) AS services,
            (SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.ward_id=w.id AND p.ts BETWEEN ? AND ?) AS fees
     FROM wards w WHERE ${sc.sql.replace("ward_id", "w.id")} ORDER BY w.name_en`,
    [today(), from, to, from, to + "T23:59:59Z", ...sc.params]
  );
  const byDidi = await db.all(
    `SELECT u.id, u.name, u.shg_name, u.ward_id,
            (SELECT COUNT(*) FROM collections c WHERE c.user_id=u.id AND c.service_date BETWEEN ? AND ?) AS services,
            (SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.user_id=u.id AND p.ts BETWEEN ? AND ?) AS fees,
            (SELECT COUNT(*) FROM attendance a WHERE a.user_id=u.id AND a.service_date BETWEEN ? AND ?) AS days
     FROM users u WHERE u.role='didi' AND u.active=1 AND ${sc.sql.replace("ward_id", "u.ward_id")}`,
    [from, to, from, to + "T23:59:59Z", from, to, ...sc.params]
  );
  const assets = await db.all(`SELECT asset_type, condition, COUNT(*) AS n FROM assets WHERE ${W} GROUP BY asset_type, condition`, P);
  const services = Number(colAgg.services) || 0;
  res.json({
    range: { from, to },
    kpi: {
      households: totalHH,
      services,
      covered: Number(colAgg.covered) || 0,
      coverage_pct: totalHH ? Math.round(Number(colAgg.covered) / totalHH * 1e3) / 10 : 0,
      today_covered: Number(todayAgg.covered) || 0,
      today_coverage_pct: totalHH ? Math.round(Number(todayAgg.covered) / totalHH * 1e3) / 10 : 0,
      wet_kg: Math.round(Number(colAgg.wet) * 10) / 10,
      dry_kg: Math.round(Number(colAgg.dry) * 10) / 10,
      hazard_kg: Math.round(Number(colAgg.hazard) * 10) / 10,
      segregation_pct: services ? Math.round(Number(colAgg.seg) / services * 1e3) / 10 : 0,
      fees_collected: Math.round(Number(payAgg.total)),
      fee_txns: Number(payAgg.n) || 0
    },
    grievances: griev,
    daily,
    by_ward: byWard.filter((w) => !req.query.block_id || w.block_id === req.query.block_id),
    by_didi: byDidi,
    assets
  });
});
var EXPORTS = {
  households: `SELECT h.code, h.head_name, h.phone, h.house_no, h.category, h.fee_slab, h.family_size,
                 b.name_en AS block, w.name_en AS ward, h.lat, h.lng, h.toilet, h.soak_pit, h.compost_pit, h.created_at
               FROM households h LEFT JOIN wards w ON w.id=h.ward_id LEFT JOIN blocks b ON b.id=w.block_id
               WHERE h.active=1 AND __SCOPE__ ORDER BY b.name_en, w.name_en, h.house_no`,
  collections: `SELECT c.service_date, c.ts, hh.code AS household_code, hh.head_name, w.name_en AS ward, b.name_en AS block,
                  u.name AS collected_by, c.wet_kg, c.dry_kg, c.hazard_kg, c.segregated, c.status, c.lat, c.lng, c.notes
                FROM collections c LEFT JOIN households hh ON hh.id=c.household_id
                LEFT JOIN wards w ON w.id=c.ward_id LEFT JOIN blocks b ON b.id=w.block_id
                LEFT JOIN users u ON u.id=c.user_id WHERE __SCOPE__ ORDER BY c.ts DESC`,
  payments: `SELECT p.receipt_no, p.ts, p.period, p.amount, p.mode, hh.code AS household_code, hh.head_name,
               w.name_en AS ward, b.name_en AS block, u.name AS collected_by
             FROM payments p LEFT JOIN households hh ON hh.id=p.household_id
             LEFT JOIN wards w ON w.id=p.ward_id LEFT JOIN blocks b ON b.id=w.block_id
             LEFT JOIN users u ON u.id=p.user_id WHERE __SCOPE__ ORDER BY p.ts DESC`,
  grievances: `SELECT g.ts, g.category, g.description, g.status, g.priority, g.raised_by_name,
                 hh.code AS household_code, w.name_en AS ward, b.name_en AS block, g.resolution, g.resolved_ts
               FROM grievances g LEFT JOIN households hh ON hh.id=g.household_id
               LEFT JOIN wards w ON w.id=g.ward_id LEFT JOIN blocks b ON b.id=w.block_id
               WHERE __SCOPE__ ORDER BY g.ts DESC`,
  assets: `SELECT a.asset_type, a.name, a.condition, a.capacity, a.ownership, w.name_en AS ward,
             b.name_en AS block, a.lat, a.lng, a.notes, a.ts
           FROM assets a LEFT JOIN wards w ON w.id=a.ward_id LEFT JOIN blocks b ON b.id=w.block_id
           WHERE __SCOPE__ ORDER BY a.asset_type, a.name`,
  attendance: `SELECT a.service_date, u.name AS didi, u.shg_name, w.name_en AS ward, a.in_ts, a.out_ts, a.lat, a.lng
               FROM attendance a LEFT JOIN users u ON u.id=a.user_id LEFT JOIN wards w ON w.id=a.ward_id
               WHERE __SCOPE__ ORDER BY a.service_date DESC`
};
async function exportRows(user, entity, query) {
  const base = EXPORTS[entity];
  if (!base) return null;
  const alias = { households: "h", collections: "c", payments: "p", grievances: "g", assets: "a", attendance: "a" }[entity];
  const sc = await scopeFor(user);
  let where = sc.sql.replace(/ward_id/g, `${alias}.ward_id`);
  const params = [...sc.params];
  if (query.from && ["collections", "attendance"].includes(entity)) {
    where += ` AND ${alias}.service_date BETWEEN ? AND ?`;
    params.push(query.from, query.to || today());
  } else if (query.from) {
    where += ` AND ${alias}.ts >= ?`;
    params.push(query.from);
  }
  if (query.ward_id) {
    where += ` AND ${alias}.ward_id = ?`;
    params.push(query.ward_id);
  }
  return db.all(base.replace("__SCOPE__", where), params);
}
app.get("/api/export/:entity.csv", auth, async (req, res) => {
  const rows = await exportRows(req.user, req.params.entity, req.query);
  if (!rows) return res.status(404).json({ error: "unknown_entity" });
  const cols = rows.length ? Object.keys(rows[0]) : ["no_data"];
  const esc = (v) => {
    if (v === null || v === void 0) return "";
    const s = String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const csv = "\uFEFF" + [cols.join(","), ...rows.map((r) => cols.map((c) => esc(r[c])).join(","))].join("\n");
  res.type("text/csv").set(
    "Content-Disposition",
    `attachment; filename="${req.params.entity}-${today()}.csv"`
  ).send(csv);
});
app.get("/api/export/:entity.xlsx", auth, async (req, res) => {
  const rows = await exportRows(req.user, req.params.entity, req.query);
  if (!rows) return res.status(404).json({ error: "unknown_entity" });
  const wb = new ExcelJS.Workbook();
  wb.creator = "Swachh Dhamtari";
  const ws = wb.addWorksheet(req.params.entity.slice(0, 30));
  const cols = rows.length ? Object.keys(rows[0]) : ["no_data"];
  ws.columns = cols.map((c) => ({ header: c.replace(/_/g, " ").toUpperCase(), key: c, width: Math.min(28, Math.max(12, c.length + 6)) }));
  rows.forEach((r) => ws.addRow(r));
  ws.getRow(1).font = { bold: true, color: { argb: "FFFFFFFF" } };
  ws.getRow(1).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF15803D" } };
  ws.views = [{ state: "frozen", ySplit: 1 }];
  ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: cols.length } };
  res.set("Content-Disposition", `attachment; filename="${req.params.entity}-${today()}.xlsx"`);
  res.type("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
  await wb.xlsx.write(res);
  res.end();
});
